-- Apply verified catalog images to an existing database using names and variants, not seed IDs.
-- Run with psql --single-transaction -v ON_ERROR_STOP=1 -f scripts/seed-images.sql
WITH images(brand_name,image_url) AS (VALUES
('Apple','https://www.pngpacks.com/uploads/data/243/IMG_YZECTwmyW4gW.png'),
('Samsung','https://www.liblogo.com/img-logo/sa428sade-samsung-logo-samsung-logo-.png'),
('Xiaomi','https://www.citypng.com/public/uploads/preview/xiaomi-xiomi-official-logo-701751694791329pih5txajgm.png?v=2026021500'),
('OPPO','https://www.liblogo.com/img-logo/op6oc5c-oppo-logo-oppo-logo-2019-download-logo-icon-png-svg.png'),
('vivo','https://zonalogo.com/assets/vivo-logo-png-svg.webp?w=768'),
('HONOR','https://aetoswire.com/storage/clients/client-3187/honor-logo.jpg'),
('realme','https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Realme_logo.svg/1920px-Realme_logo.svg.png?_=20230228121816'),
('OnePlus','https://image01-in.oneplus.net/shop/202003/20/1-M00-12-16-rB8bwl50LA2AfmEjAABcEXplEJY678.png'),
('Nothing','https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Nothing_logo.svg/3840px-Nothing_logo.svg.png'),
('Anker','https://mma.prnewswire.com/media/1705177/Anker_logo.jpg?p=facebook')
) UPDATE public.brand b SET image_url=i.image_url, updated_at=CURRENT_TIMESTAMP FROM images i WHERE lower(b.brand_name)=lower(i.brand_name) AND b.image_url IS DISTINCT FROM i.image_url;
