) UPDATE public.product_model m SET image_url=i.image_url, updated_at=CURRENT_TIMESTAMP FROM images i JOIN public.brand b ON lower(b.brand_name)=lower(i.brand_name) WHERE m.model_name=i.model_name AND m.color IS NOT DISTINCT FROM i.color AND m.storage_capacity IS NOT DISTINCT FROM i.storage_capacity AND m.brand_id=b.brand_id AND m.image_url IS DISTINCT FROM i.image_url;
